const sequence=document.querySelector('.facility-sequence'),section=sequence.querySelector('.facility'),images=[...section.querySelectorAll('.facility-media img')],buttons=[...section.querySelectorAll('[data-production]')],reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const clamp=v=>Math.max(0,Math.min(1,v)),ease=v=>{v=clamp(v);return v*v*(3-2*v)};
const chapters=[['01 / BLENDING','Consistency begins here.','Selected base oils and additives come together through controlled blending.','01 / CONTROLLED BLENDING'],['02 / LABORATORY','Checked before release.','Lubricant samples are checked against product specifications before release.','02 / PRODUCT CHECKS'],['03 / FILLING','Ready for the road ahead.','Approved lubricant moves through filling and packaging for distribution.','03 / PRECISION FILLING']];
let current=-1,frame=0;
function select(n){if(n===current)return;current=n;const c=chapters[n];section.querySelector('.facility-chapter-index').textContent=c[0];section.querySelector('.facility-chapter h3').textContent=c[1];section.querySelector('.facility-chapter p').textContent=c[2];section.querySelector('.facility-image-caption>span').textContent=c[3];section.querySelector('.facility-image-index').textContent=String(n+1).padStart(2,'0');buttons.forEach((b,i)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-pressed',String(i===n))});images.forEach((im,i)=>im.setAttribute('aria-hidden',String(i!==n)))}
function render(){frame=0;if(reduced||document.hidden)return;const r=sequence.getBoundingClientRect(),top=innerWidth<=700?100:innerHeight<=760?145:150,p=clamp((top-r.top)/Math.max(1,r.height-section.offsetHeight));if(r.top>innerHeight||r.bottom<0)return;const n=p<.34?0:p<.67?1:2,a=ease((p-.285)/.11),b=ease((p-.615)/.11),weights=[1-a,a*(1-b),b];select(n);images.forEach((im,i)=>{im.style.opacity=weights[i];im.style.transform=`scale(${1.07-weights[i]*.04}) translate3d(${(1-weights[i])*12}px,0,0)`});const reveal=ease(Math.min(Math.abs(p-.34),Math.abs(p-.67))/.055);section.querySelector('.facility-chapter').style.opacity=reveal;section.querySelector('.facility-chapter').style.transform=`translateY(${(1-reveal)*12}px)`;section.querySelector('.facility-image-caption').style.opacity=reveal;buttons.forEach((button,i)=>button.style.setProperty('--stage-progress',clamp((p-i/3)*3)))}
function start(){if(!frame)frame=requestAnimationFrame(render)}
buttons.forEach((button,i)=>button.addEventListener('click',()=>{if(reduced){select(i);images.forEach((im,n)=>im.style.opacity=n===i?1:0);return}const r=sequence.getBoundingClientRect(),top=innerWidth<=700?100:innerHeight<=760?145:150;scrollTo({top:scrollY+r.top-top+(r.height-section.offsetHeight)*(i+.18)/3,behavior:'smooth'})}));
addEventListener('scroll',start,{passive:true});addEventListener('resize',start,{passive:true});document.addEventListener('visibilitychange',start);select(0);start();
